+func repoRelativePath(p, repoRoot string) string {
+	p = strings.TrimSpace(p)
+	if repoRoot == "" {
+		return p
+	}
+	if s, ok := cleanAbsPath(p); ok {
+		if rel, ok := pathUnderRoot(s, repoRoot); ok {
+			return rel
+		}
+	}
+	return p
