package cli

import (
	"encoding/json"
	"path"
	"regexp"
	"sort"
	"strings"

	clibase "github.com/entireio/entire-brain/internal/cli/internal/base"
	"github.com/entireio/entire-brain/internal/cli/internal/factstore"
	patterncore "github.com/entireio/entire-brain/internal/cli/patterns"
)

// Pattern corpus enrichment (V2, Phase 2): turn episodes into brain events by
// linking the operational evidence — command exit/failure, files touched,
// way-of-working meta hits, and durable-fact links — so Phase 3 candidates can be
// corroborated across intent + method + evidence + outcome. All deterministic and
// token-free; missing optional sources (facts, semantic) degrade to empty.

type corpusCommand struct {
	head     string
	raw      string
	line     int
	callID   string
	exitCode *int
	failed   bool
}

type corpusFileRef struct {
	path   string
	action string // read | write | edit | add | delete
	line   int
}

var (
	reExitCode  = regexp.MustCompile(`(?i)(?:exited with code|exit code:?)\s*(\d+)`)
	rePatchFile = regexp.MustCompile(`(?m)^\*\*\* (Add|Update|Delete) File: (.+)$`)
	// git commit confirmation: "[branch hash] subject" — local evidence only.
	reCommitConfirm = regexp.MustCompile(`\[([A-Za-z0-9._/+-]+) ([0-9a-f]{7,40})\] (.+)`)
)

type corpusCommit struct {
	hash, branch, subject string
	line                  int
}

// corpusCommits extracts git commits an episode landed from the local
// `[branch hash] subject` confirmation lines in its work text. No network; the
// subject is redacted and truncated.
func corpusCommits(workText string) []corpusCommit {
	seen := map[string]bool{}
	var out []corpusCommit
	for i, line := range strings.Split(workText, "\n") {
		m := reCommitConfirm.FindStringSubmatch(line)
		if m == nil {
			continue
		}
		hash := m[2]
		if seen[hash] {
			continue
		}
		seen[hash] = true
		out = append(out, corpusCommit{
			hash:    hash,
			branch:  m[1],
			subject: clibase.RedactText(clibase.TruncateString(strings.TrimSpace(m[3]), 160)),
			line:    i + 1,
		})
	}
	return out
}

// claudeFileTools maps Claude/pi file tool names to a file action.
var claudeFileTools = map[string]string{
	"read": "read", "view": "read", "cat": "read",
	"write": "write", "create": "write",
	"edit": "edit", "str_replace": "edit", "str_replace_editor": "edit", "apply_patch": "edit",
}

// corpusEpisodeOps extracts ordered tool calls, shell commands (with exit/failure
// correlated by call id), and file references from one episode's work segment.
// repoRoot is the session's checkout root from codexSessionRoot, or "" when
// unknown; a compact codex FileChange's absolute path under it is stored
// relative to it.
func corpusEpisodeOps(workText, repoRoot string) (tools []corpusToolOp, commands []corpusCommand, files []corpusFileRef) {
	exitByCall := map[string]int{}
	failedByCall := map[string]bool{}
	for i, line := range strings.Split(workText, "\n") {
		line = strings.TrimSpace(line)
		if !strings.HasPrefix(line, "{") {
			continue
		}
		var obj map[string]any
		if json.Unmarshal([]byte(line), &obj) != nil {
			continue
		}
		ln := i + 1
		switch jsonString(obj["type"]) {
		case "response_item":
			p := jsonMap(obj["payload"])
			switch jsonString(p["type"]) {
			case "function_call":
				name := strings.ToLower(strings.TrimSpace(jsonString(p["name"])))
				tools = append(tools, corpusToolOp{name: name, line: ln})
				if cmd := shellCommandFromInput(name, p["arguments"]); cmd != "" {
					if h := normalizeCommand(cmd); h != "" {
						commands = append(commands, corpusCommand{head: h, raw: cmd, line: ln, callID: jsonString(p["call_id"])})
					}
				}
			case "custom_tool_call":
				name := strings.ToLower(strings.TrimSpace(jsonString(p["name"])))
				tools = append(tools, corpusToolOp{name: name, line: ln})
				files = append(files, patchFiles(jsonString(p["input"]), ln)...)
			case "function_call_output", "custom_tool_call_output":
				if id := jsonString(p["call_id"]); id != "" {
					if code, ok := parseExitCode(jsonString(p["output"])); ok {
						exitByCall[id] = code
					}
				}
			case "patch_apply_end":
				if id := jsonString(p["call_id"]); id != "" {
					if code, ok := parseExitCode(jsonString(p["stdout"])); ok {
						exitByCall[id] = code
					}
				}
			}
		case "assistant", "message":
			msg := jsonMap(obj["message"])
			if jsonString(obj["type"]) == "message" && jsonString(msg["role"]) != "assistant" {
				continue
			}
			content := msg["content"]
			if len(msg) == 0 {
				// ETF compact records carry the content blocks at the record's
				// top level (see distillConversationText).
				content = obj["content"]
				if strings.EqualFold(jsonString(obj["agent"]), "codex") {
					compactCodexResults(content, exitByCall, failedByCall)
				}
			}
			t, c, f := claudeContentOps(content, repoRoot, ln)
			tools = append(tools, t...)
			commands = append(commands, c...)
			files = append(files, f...)
		}
	}
	// Correlate exit codes, and failures that carry none, to their commands.
	for i := range commands {
		if commands[i].callID == "" {
			continue
		}
		if code, ok := exitByCall[commands[i].callID]; ok {
			c := code
			commands[i].exitCode = &c
			commands[i].failed = code != 0
		} else if failedByCall[commands[i].callID] {
			commands[i].failed = true
		}
	}
	return tools, commands, dedupeFileRefs(files)
}

func claudeContentOps(content any, repoRoot string, ln int) (tools []corpusToolOp, commands []corpusCommand, files []corpusFileRef) {
	blocks, ok := content.([]any)
	if !ok {
		return nil, nil, nil
	}
	for _, b := range blocks {
		bm := jsonMap(b)
		switch jsonString(bm["type"]) {
		case "tool_use", "tool":
			name := strings.ToLower(strings.TrimSpace(firstNonEmptyString(bm["name"], bm["tool"])))
			if name == "" {
				continue
			}
			tools = append(tools, corpusToolOp{name: name, line: ln})
			if cmd := shellCommandFromInput(name, bm["input"]); cmd != "" {
				if h := normalizeCommand(cmd); h != "" {
					commands = append(commands, corpusCommand{head: h, raw: cmd, line: ln, callID: jsonString(bm["id"])})
				}
			}
			if action, isFile := claudeFileTools[name]; isFile {
				if p := filePathFromInput(bm["input"]); p != "" {
					files = append(files, corpusFileRef{path: p, action: action, line: ln})
				} else if name == "apply_patch" {
					// Compact codex has no path: the converter wraps the
					// custom_tool_call patch text as {"input": <patch>}, so read
					// it the way the native custom_tool_call case does.
					files = append(files, patchFiles(jsonString(asObject(bm["input"])["input"]), ln)...)
				}
			}
			if name == "filechange" {
				files = append(files, fileChangeFiles(bm["input"], repoRoot, ln)...)
			}
		}
	}
	return tools, commands, files
}

// fileChangeFiles reads the file refs of a compact codex FileChange, the tool
// the cli's item path (a current Codex rollout) writes for an edit:
// {"changes":[{"path","kind","move_path","diff"}]}. kind is add, delete or
// update; an update with a move_path deletes path and adds move_path. Like an
// apply_patch, every change counts whatever its result status.
func fileChangeFiles(input any, repoRoot string, ln int) []corpusFileRef {
	changes, _ := asObject(input)["changes"].([]any)
	var out []corpusFileRef
	for _, c := range changes {
		cm := jsonMap(c)
		p := repoRelativePath(jsonString(cm["path"]), repoRoot)
		if p == "" {
			continue
		}
		kind := strings.ToLower(strings.TrimSpace(jsonString(cm["kind"])))
		if move := repoRelativePath(jsonString(cm["move_path"]), repoRoot); move != "" && kind == "update" {
			out = append(out, corpusFileRef{path: p, action: "delete", line: ln}, corpusFileRef{path: move, action: "add", line: ln})
			continue
		}
		action := "edit"
		if kind == "add" || kind == "delete" {
			action = kind
		}
		out = append(out, corpusFileRef{path: p, action: action, line: ln})
	}
	return out
}

// repoRelativePath is p relative to repoRoot (a clean forward-slash path from
// codexSessionRoot) when p is inside it, so it matches the repo-relative paths
// apply_patch and the semantic index use. Any other path, including one with
// a ".." segment (see cleanAbsPath), is returned trimmed but otherwise as
// written.
func repoRelativePath(p, repoRoot string) string {
	p = strings.TrimSpace(p)
	if repoRoot == "" {
		return p
	}
	if s, ok := cleanAbsPath(p); ok {
		if rel, ok := pathUnderRoot(s, repoRoot); ok {
			return rel
		}
	}
	return p
}

// codexSessionRoot is the checkout a compact codex session's FileChange paths
// are under, worked out from the session itself: a FileChange path is
// absolute, and the session's checkpoint records the repo-relative files it
// touched (files_touched), so a path that ends in one of them, split at a
// "/", gives a candidate root.
//
// A candidate scores one for each distinct session path that is a touched
// file under it, and the highest score wins. Every split of every path counts,
// so a checkout named like one of its own directories (/work/repo with
// repo/main.go) still gets its full score, and repeated edits of one file
// count once. A tie is ambiguous, whatever else the tied roots hold, so it
// gives "" and the paths are stored as written rather than linked to the
// wrong files. So does a session with any ".." path (see
// codexFileChangePaths), and one with no FileChange or no path that ends in

		fingerprint, err := branchFactFingerprint(branch)
		if err != nil {
			return false, err
		}
		return patterncore.CorpusMeta(db, patternCorpusFactsMetaKey(branch)) == fingerprint, nil
	}
	present := map[string]bool{}
	for _, s := range sessions {
		rel := strings.TrimSpace(s.TranscriptPath)
		if rel == "" {
			continue
		}
		id := repoKey + "/" + filepath.ToSlash(rel)
		content, size, mtime, sha, readErr := readPatternCorpusTranscript(context.Background(), brainDir, filepath.ToSlash(rel))
		if readErr != nil {
			if errors.Is(readErr, os.ErrNotExist) {
				return &historySessionInventoryError{
					Path:   filepath.ToSlash(rel),
					Reason: "manifest-listed canonical transcript is missing; refusing a partial corpus publication",
					Err:    readErr,
				}
			}
			return readErr
		}
		present[id] = true
		factsFresh, err := factsCurrentFor(s.Branch)
		if err != nil {
			return err
		}
		if factsFresh && corpusSessionUnchanged(db, id, size, mtime, sha, s.LatestCheckpoint) {
			continue
		}
		if err := indexSessionIntoCorpus(db, repoKey, s, id, rel, content, size, mtime, sha, factsByBranch); err != nil {
			return err
		}
		onPatternCorpusSessionIndexed(id)
	}

	// Prune sessions no longer in the manifest (deleted transcripts).
	if err := pruneCorpusSessions(db, present); err != nil {
		return err
	}

	// Link episodes to semantic symbols (if a semantic index exists), then
	// rebuild candidate patterns, then materialize the synapse explanation graph.
	var sem *semanticSourceManifest
	if len(graph) > 0 {
		sem = graph[0].source(brainDir, manifest)
		if err := graph[0].Context.Err(); err != nil {
			return err
		}
	}
	if err := linkEpisodeSymbols(db, brainDir, sem); err != nil {
		return err
	}
	if err := patterncore.BuildCandidates(db, repoKey, now); err != nil {
		return err
	}
	// Episode shapes (deterministic, token-free). Themes are NOT built here:
	// they are agent-proposed semantic clusters, created only by the explicit
	// `patterns verify --themes` (egress-gated) — refresh stays token-free.
	if err := classifyEpisodeShapes(db, now); err != nil {
		return err
	}
	if err := patterncore.BuildSynapses(db, now); err != nil {
		return err
	}
	// Record a fingerprint for every branch that HAS facts. Branches that only
	// have sessions need no loop of their own: the freshness gate above calls
	// branchFactFingerprint(s.Branch) for each indexed session and memoizes
	// it, so they are already in the map. (A loop over sessions was written
	// here first and a weakening run showed removing it changed nothing --
	// dead code, deleted rather than kept with a guard that cannot justify
	// it.)
	for branch := range factsByBranch {
		if _, err := branchFactFingerprint(branch); err != nil {
			return err
		}
	}
	factsMeta := map[string]string{}
	for branch, fingerprint := range factFingerprintByBranch {
		factsMeta[patternCorpusFactsMetaKey(branch)] = fingerprint
	}
	if len(factsMeta) > 0 {
		if err := setCorpusMeta(db, factsMeta); err != nil {
			return err
		}
	}
	if err := setCorpusMeta(db, map[string]string{
		"schema_version":          strconv.Itoa(patternCorpusSchemaVersion),
		"pattern_indexer_version": strconv.Itoa(patterncore.IndexerVersion),
		"facts_fingerprint":       factFingerprint,
		"repo_key":                repoKey,
		"generated_at":            now.UTC().Format(time.RFC3339),
		"sessions_fingerprint": func() string {
			if manifest == nil || manifest.Sources == nil {
				return ""
			}
			return sessionSourceFingerprint(manifest.Sources.Sessions)
		}(),
	}); err != nil {
		return err
	}
	run, err := patterncore.RunFromStaging(db, now)
	if err != nil {
		return err
	}
	if err := patterncore.FinalizeCorpusStagingLocked(brainDir, path, db, patterncore.DecodeCorpusPublication); err != nil {
		return err
	}
	closed = true
	// Operational run history describes only successfully published corpora.
	// A failed staging build or commit must leave both the old corpus and its
	// last-run report intact.
	_ = patterncore.AppendRun(brainDir, run)
	return nil
}

func loadPatternCorpusManifest(brainDir string) (*exportManifest, error) {
	// Derivation must use the same header-first, strict version classifier as
	// every other Brain-manifest consumer. In particular, never partially decode
	// or normalize a vNext document into the current schema before rebuilding.
	return bmanifest.Load(brainDir)
}

// Source anchors in both document and JSONL transcripts use physical lines.
func patternTranscriptEndLine(content string) int {
	content = strings.TrimRight(content, "\r\n")
	if content == "" {
		return 0
	}
	return strings.Count(content, "\n") + 1
}

// corpusSessionUnchanged reports whether a session's stored episodes are
// still what indexing it now would give. Besides the transcript and the
// indexer version, that covers the checkpoint the session was exported from:
// a later checkpoint can carry other files_touched for the same transcript,
// and a compact codex session's FileChange root comes from them.
func corpusSessionUnchanged(db *sql.DB, id string, size, mtime int64, sha, checkpointID string) bool {
	var (
		gotSize, gotMtime  int64
		gotSha, checkpoint string
		parser             int
	)
	err := db.QueryRow(`SELECT size, mtime_unix_nano, content_sha, parser_version, COALESCE(checkpoint_id, '') FROM indexed_sessions WHERE id = ?`, id).
		Scan(&gotSize, &gotMtime, &gotSha, &parser, &checkpoint)
	if err != nil {
		return false
	}
	return gotSize == size && gotMtime == mtime && gotSha == sha && parser == patterncore.IndexerVersion && checkpoint == checkpointID
}

func indexSessionIntoCorpus(db *sql.DB, repoKey string, s exportSession, id, rel string, content []byte, size, mtime int64, sha string, factsByBranch map[string][]factRecord) error {
	segments := transcriptEpisodeSegments(string(content))

	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	// Replace: delete this session's episodes (cascades children) + its row.
	if _, err := tx.Exec(`DELETE FROM episodes WHERE repo_key = ? AND session_id = ?`, repoKey, s.SessionID); err != nil {
		return err
	}
	if _, err := tx.Exec(`DELETE FROM indexed_sessions WHERE id = ?`, id); err != nil {
		return err
	}

	author := ""
	if len(s.Authors) > 0 {
		author = s.Authors[0].Name
	}
	createdAt := ""
	if !s.CreatedAt.IsZero() {
		createdAt = s.CreatedAt.UTC().Format(time.RFC3339)
	}

	endOfTranscript := patternTranscriptEndLine(string(content))
	// A compact codex FileChange path is absolute. The session's own
	// checkpoint says which checkout it was under, so the stored path is
	// repo-relative whichever checkout or machine the session ran in, and
	// whichever one builds the corpus.
	repoRoot := codexSessionRoot(string(content), s.FilesTouched)
	episodeCount := 0
	for ord, seg := range segments {
		feedback := ""
		if ord+1 < len(segments) {
			feedback = segments[ord+1].Request.Text
		}
		committed := workCommitted(seg.WorkText)
		outcome, outcomeSource := corpusOutcome(feedback, committed)
		tools, commands, files := corpusEpisodeOps(seg.WorkText, repoRoot)
		exitFails := 0
		for _, c := range commands {
			if c.failed {
				exitFails++
			}
		}

		startLine := seg.Request.Line
		endLine := startLine
		if ord+1 == len(segments) {
			endLine = max(startLine, endOfTranscript)
		} else if segments[ord+1].Request.Line > startLine {
			endLine = segments[ord+1].Request.Line - 1
		}

		epID := "episode:" + base.HexSHA(repoKey+"\x00"+filepath.ToSlash(rel)+"\x00"+strconv.Itoa(ord)+"\x00"+strconv.Itoa(startLine))
		epKey := repoKey + "/" + filepath.ToSlash(rel) + "#" + strconv.Itoa(ord)

		if _, err := tx.Exec(`INSERT INTO episodes
			(id, episode_key, repo_key, workspace, session_id, checkpoint_id, turn_id, turn_ord, branch, author_name, agent, created_at,
			 source_path, start_line, end_line, intent_raw, intent_sig, n_tools, tool_mix, files, n_cmds, exit_fails, outcome, outcome_source)
			VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
